import math
from itertools import combinations

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def generate_sets(n, k, m):
    sets = []
    for _ in range(n):
        # Generate a set of 4 distinct integers where gcd(s_i, s_j) = k for all i != j
        found = False
        while not found:
            set_ = [i * k for i in range(1, 5)]
            if max(set_) <= m:
                found = all(gcd(set_[i], set_[j]) == k for i in range(4) for j in range(i + 1, 4))
            if not found:
                set_[0] += 1
        sets.append(set_)
    return sets

def main():
    n, k = map(int, input().split())
    m = 4 * k  # Start with the minimum possible m
    sets = generate_sets(n, k, m)
    print(m)
    for s in sets:
        print(*s)

if __name__ == "__main__":
    main()
